use std::env;
use std::fs;
use std::io::{self, Read};
use std::path::{Path, PathBuf};
use std::collections::HashMap;

mod font;
mod options;
mod render;
mod smush;

use font::Font;
use options::Options;
use render::render_text;

fn main() {
    let args: Vec<String> = env::args().collect();

    let opts = options::parse_args(&args);

    // Handle info codes
    if let Some(code) = opts.info_code {
        handle_info_code(code, &opts);
        return;
    }

    // Handle version
    if opts.version {
        print_version();
        return;
    }

    // Load font
    let font_path = find_font(&opts);
    let font = match Font::load(&font_path) {
        Ok(f) => f,
        Err(e) => {
            eprintln!("executable: {}: {}", opts.font, e);
            std::process::exit(1);
        }
    };

    // Get input text
    let text = if let Some(ref msg) = opts.message {
        msg.clone()
    } else {
        let mut buffer = String::new();
        io::stdin().read_to_string(&mut buffer).unwrap();
        buffer.trim_end().to_string()
    };

    // Render text
    let output = render_text(&text, &font, &opts);
    print!("{}", output);
}

fn find_font(opts: &Options) -> PathBuf {
    let font_dir = &opts.font_dir;
    let font_name = &opts.font;

    // Try with .flf extension
    let candidates = vec![
        font_dir.join(format!("{}.flf", font_name)),
        font_dir.join(&font_name),
        PathBuf::from(format!("{}.flf", font_name)),
        PathBuf::from(&font_name),
    ];

    for candidate in candidates {
        if candidate.exists() {
            return candidate;
        }
    }

    // Return the first choice anyway (will error when trying to open)
    font_dir.join(format!("{}.flf", font_name))
}

fn handle_info_code(code: i32, opts: &Options) {
    match code {
        0 => {
            println!("FIGlet Copyright (C) 1991-2012 Glenn Chappell, Ian Chai, John Cowan,");
            println!("Christiaan Keet and Claudio Matsuoka");
            println!("Internet: <info@figlet.org> Version: 2.2.5, date: 31 May 2012");
            println!("");
            println!("FIGlet, along with the various FIGlet fonts and documentation, may be");
            println!("freely copied and distributed.");
            println!("");
            println!("If you use FIGlet, please send an e-mail message to <info@figlet.org>.");
            println!("");
            println!("The latest version of FIGlet is available from the web site,");
            println!("\thttp://www.figlet.org/");
            println!("");
            println!("Usage: executable [ -cklnoprstvxDELNRSWX ] [ -d fontdirectory ]");
            println!("              [ -f fontfile ] [ -m smushmode ] [ -w outputwidth ]");
            println!("              [ -C controlfile ] [ -I infocode ] [ message ]");
        }
        1 => {
            println!("20205");
        }
        2 => {
            println!("{}", opts.font_dir.display());
        }
        3 => {
            println!("{}", opts.font);
        }
        4 => {
            println!("{}", opts.output_width);
        }
        5 => {
            println!("flf2 tlf2");
        }
        _ => {}
    }
}

fn print_version() {
    println!("FIGlet Copyright (C) 1991-2012 Glenn Chappell, Ian Chai, John Cowan,");
    println!("Christiaan Keet and Claudio Matsuoka");
    println!("Internet: <info@figlet.org> Version: 2.2.5, date: 31 May 2012");
    println!("");
    println!("FIGlet, along with the various FIGlet fonts and documentation, may be");
    println!("freely copied and distributed.");
    println!("");
    println!("If you use FIGlet, please send an e-mail message to <info@figlet.org>.");
    println!("");
    println!("The latest version of FIGlet is available from the web site,");
    println!("\thttp://www.figlet.org/");
    println!("");
    println!("Usage: executable [ -cklnoprstvxDELNRSWX ] [ -d fontdirectory ]");
    println!("              [ -f fontfile ] [ -m smushmode ] [ -w outputwidth ]");
    println!("              [ -C controlfile ] [ -I infocode ] [ message ]");
}
