#[derive(Debug, Clone)]
pub struct Font {
    pub height: usize,
    pub baseline: usize,
    pub max_width: usize,
    pub old_layout: i32,
    pub comment_lines: usize,
    pub print_direction: i32,
    pub full_layout: i32,
    pub code_tag_count: i32,

    pub characters: HashMap<char, Vec<String>>,
    pub required_chars: Vec<char>,
}

impl Font {
    pub fn load<P: AsRef<Path>>(path: P) -> Result<Self, io::Error> {
        let contents = fs::read_to_string(path)?;

        let lines: Vec<&str> = contents.lines().collect();
        if lines.is_empty() {
            return Err(io::Error::new(io::ErrorKind::InvalidData, "Empty font file"));
        }

        let header: Vec<&str> = lines[0].split_whitespace().collect();
        if header.is_empty() || !header[0].starts_with("flf") {
            return Err(io::Error::new(io::ErrorKind::InvalidData, "Invalid font header"));
        }

        let height: usize = header.get(1).and_then(|s| s.parse().ok()).unwrap_or(6);
        let baseline: usize = header.get(2).and_then(|s| s.parse().ok()).unwrap_or(5);
        let max_width: usize = header.get(3).and_then(|s| s.parse().ok()).unwrap_or(0);
        let old_layout: i32 = header.get(4).and_then(|s| s.parse().ok()).unwrap_or(0);
        let comment_lines: usize = header.get(5).and_then(|s| s.parse().ok()).unwrap_or(0);
        let print_direction: i32 = header.get(6).and_then(|s| s.parse().ok()).unwrap_or(0);
        let full_layout: i32 = header.get(7).and_then(|s| s.parse().ok()).unwrap_or(0);
        let code_tag_count: i32 = header.get(8).and_then(|s| s.parse().ok()).unwrap_or(0);

        let mut font = Font {
            height,
            baseline,
            max_width,
            old_layout,
            comment_lines,
            print_direction,
            full_layout,
            code_tag_count,
            characters: HashMap::new(),
            required_chars: vec![],
        };

        // Skip comment lines
        let mut line_idx = 1 + comment_lines;

        // Load required characters (ASCII 32-126)
        for code in 32..=126 {
            let ch = (code as u8) as char;
            if let Some(lines_for_char) = load_char_lines(&lines, &mut line_idx, height) {
                font.characters.insert(ch, lines_for_char);
            }
        }

        Ok(font)
    }

    pub fn get_char(&self, ch: char) -> Option<&Vec<String>> {
        self.characters.get(&ch)
    }
}

fn load_char_lines(lines: &[&str], line_idx: &mut usize, height: usize) -> Option<Vec<String>> {
    let mut result = Vec::new();

    for _ in 0..height {
        if *line_idx >= lines.len() {
            return None;
        }

        let mut line = lines[*line_idx].to_string();

        // Remove the line ending character (@ or @@)
        if line.ends_with("@@") {
            line.pop();
            line.pop();
        } else if line.ends_with("@") {
            line.pop();
        }

        result.push(line);
        *line_idx += 1;
    }

    Some(result)
}
