// Smushing and kerning logic for FIGlet

pub fn smush_chars(left: char, right: char) -> Option<char> {
    match (left, right) {
        ('|', '|') => Some('|'),
        ('/', '\\') => Some('|'),
        ('\\', '/') => Some('X'),
        ('[', ']') => Some('|'),
        ('{', '}') => Some('|'),
        ('(', ')') => Some('|'),
        ('_', '-') => Some('_'),
        ('-', '_') => Some('-'),
        _ => None,
    }
}
