use std::path::PathBuf;

#[derive(Debug, Clone)]
pub struct Options {
    pub font: String,
    pub font_dir: PathBuf,
    pub message: Option<String>,
    pub justify: Justify,
    pub width: Option<usize>,
    pub output_width: usize,
    pub kerning: bool,
    pub full_width: bool,
    pub overlap: bool,
    pub smushing_mode: SmushMode,
    pub right_to_left: bool,
    pub version: bool,
    pub info_code: Option<i32>,
    pub paragraph: bool,
    pub layout: LayoutMode,
    pub control_file: Option<String>,
    pub new_layout: Option<i32>,
}

#[derive(Debug, Clone, Copy, PartialEq)]
pub enum Justify {
    Left,
    Center,
    Right,
    Auto,
}

#[derive(Debug, Clone, Copy, PartialEq)]
pub enum SmushMode {
    Default,
    Smushing,
    Kerning,
    None,
    Old,
}

#[derive(Debug, Clone, Copy, PartialEq)]
pub enum LayoutMode {
    Default,
    English,
    Deutsch,
}

impl Default for Options {
    fn default() -> Self {
        Options {
            font: "standard".to_string(),
            font_dir: PathBuf::from("fonts"),
            message: None,
            justify: Justify::Auto,
            width: None,
            output_width: 80,
            kerning: false,
            full_width: false,
            overlap: false,
            smushing_mode: SmushMode::Default,
            right_to_left: false,
            version: false,
            info_code: None,
            paragraph: false,
            layout: LayoutMode::Default,
            control_file: None,
            new_layout: None,
        }
    }
}

pub fn parse_args(args: &[String]) -> Options {
    let mut opts = Options::default();
    let mut i = 1;
    let mut message_parts = Vec::new();

    while i < args.len() {
        let arg = &args[i];

        if arg.starts_with('-') && arg.len() > 1 {
            let flags = &arg[1..];

            for (j, ch) in flags.chars().enumerate() {
                match ch {
                    'c' => opts.justify = Justify::Center,
                    'l' => opts.justify = Justify::Left,
                    'r' => opts.justify = Justify::Right,
                    'x' => opts.justify = Justify::Auto,
                    'k' => opts.kerning = true,
                    's' => opts.smushing_mode = SmushMode::Smushing,
                    'S' => opts.smushing_mode = SmushMode::Old,
                    'n' => opts.smushing_mode = SmushMode::None,
                    'o' => opts.overlap = true,
                    'W' => opts.full_width = true,
                    'p' => opts.paragraph = true,
                    'v' => opts.version = true,
                    'R' => opts.right_to_left = true,
                    'L' => opts.right_to_left = false,
                    'E' => opts.layout = LayoutMode::English,
                    'D' => opts.layout = LayoutMode::Deutsch,
                    'X' => opts.layout = LayoutMode::Default,
                    'N' => opts.control_file = None,
                    't' => {
                        // Terminal width - try to get terminal width
                        if let Ok(size) = get_terminal_size() {
                            opts.output_width = size;
                        }
                    }
                    'd' => {
