use crate::font::Font;
use crate::options::{Options, Justify};

pub fn render_text(text: &str, font: &Font, opts: &Options) -> String {
    if text.is_empty() {
        return String::new();
    }

    // Handle paragraph mode
    let lines: Vec<&str> = if opts.paragraph {
        text.split('\n').collect()
    } else {
        vec![text]
    };

    let mut output = String::new();

    for (line_idx, line) in lines.iter().enumerate() {
        let rendered = render_line(line, font, opts);
        output.push_str(&rendered);
    }

    output
}

fn render_line(text: &str, font: &Font, opts: &Options) -> String {
    if text.is_empty() {
        return String::new();
    }

    let chars: Vec<char> = if opts.right_to_left {
        text.chars().rev().collect()
    } else {
        text.chars().collect()
    };

    // Get character lines
    let mut char_lines: Vec<Vec<String>> = Vec::new();
    for ch in &chars {
        if let Some(lines) = font.get_char(*ch) {
            char_lines.push(lines.clone());
        } else {
            // Use space for unknown characters
            if let Some(lines) = font.get_char(' ') {
                char_lines.push(lines.clone());
            }
        }
    }

    if char_lines.is_empty() {
        return String::new();
    }

    // Combine character lines horizontally
    let mut output_lines = vec![String::new(); font.height];

    for (i, char_line) in char_lines.iter().enumerate() {
        if i > 0 {
            // Apply smushing/kerning rules
            apply_spacing(&mut output_lines, char_line, font, opts);
        } else {
            // First character - just add it
            for (line_idx, line) in char_line.iter().enumerate() {
                output_lines[line_idx] = line.clone();
            }
        }
    }

    // Handle justification
    let result = apply_justification(&output_lines, opts);

    result
}

fn apply_spacing(output_lines: &mut [String], char_line: &[String], font: &Font, opts: &Options) {
    for (line_idx, line) in char_line.iter().enumerate() {
        if line_idx < output_lines.len() {
            if opts.kerning {
                apply_kerning(&mut output_lines[line_idx], line);
            } else if opts.full_width {
                output_lines[line_idx].push(' ');
                output_lines[line_idx].push_str(line);
            } else if opts.overlap {
                apply_overlap(&mut output_lines[line_idx], line);
            } else {
                // Default smushing
                apply_smushing(&mut output_lines[line_idx], line);
            }
        }
    }
}

fn apply_kerning(output: &mut String, new_char: &str) {
    // Remove trailing spaces from output and add new char
    while output.ends_with(' ') {
        output.pop();
    }
    output.push_str(new_char);
}

fn apply_overlap(output: &mut String, new_char: &str) {
    // Remove trailing spaces and one more space from output
    while output.ends_with(' ') {
        output.pop();
    }
    output.push_str(new_char);
}

fn apply_smushing(output: &mut String, new_char: &str) {
    // Default smushing algorithm
    // Remove trailing spaces from output
    let output_trimmed_end = output.trim_end();
    let trimmed_len = output_trimmed_end.len();

    // Remove leading spaces from new_char
    let new_char_trimmed = new_char.trim_start();

    if !output_trimmed_end.is_empty() && !new_char_trimmed.is_empty() {
        // Both have content
        let last_char = output_trimmed_end.chars().last().unwrap_or(' ');
        let first_char = new_char_trimmed.chars().next().unwrap_or(' ');

        // Check if these characters can smush together
        if can_smush(last_char, first_char) {
            // Smush: overlap the characters
            output.truncate(trimmed_len);
            output.push_str(&new_char_trimmed[1..]);
        } else {
            // Cannot smush, add with space
            output.truncate(trimmed_len);
            output.push(' ');
            output.push_str(new_char_trimmed);
        }
    } else if !output_trimmed_end.is_empty() {
        // Only output has content
        output.truncate(trimmed_len);
    } else if !new_char_trimmed.is_empty() {
        // Only new_char has content
        *output = new_char_trimmed.to_string();
    } else {
        // Both empty/spaces - just add one space
        if !output.is_empty() {
            output.push_str(new_char);
        } else {
            output.push_str(new_char);
        }
    }
}

fn can_smush(left: char, right: char) -> bool {
    // Smushing rules - characters that can overlap
    match (left, right) {
        // Same character
        (c1, c2) if c1 == c2 => true,
        // Line characters
        ('|', '|') => true,
        // Slash patterns
        ('/', '\\') => true,
        ('\\', '/') => true,
        _ => false,
    }
}

fn apply_justification(lines: &[String], opts: &Options) -> String {
    let justify = opts.justify;
    let max_width = lines.iter().map(|l| l.len()).max().unwrap_or(0);
    let mut result = String::new();

    for line in lines {
        let trimmed = line.trim_end();

        let padded = match justify {
            Justify::Center => {
                let padding = (opts.output_width.saturating_sub(trimmed.len())) / 2;
                format!("{}{}", " ".repeat(padding), trimmed)
            }
            Justify::Right => {
                let padding = opts.output_width.saturating_sub(trimmed.len());
                format!("{}{}", " ".repeat(padding), trimmed)
            }
            Justify::Left | Justify::Auto => trimmed.to_string(),
        };

        result.push_str(&padded);
        result.push('\n');
    }

    result
}
