use crate::font::Font;
use crate::options::{Options, Justify};

pub fn render_text(text: &str, font: &Font, opts: &Options) -> String {
    if text.is_empty() {
        return String::new();
    }

    // Handle paragraph mode
    let lines: Vec<&str> = if opts.paragraph {
        text.split('\n').collect()
    } else {
        vec![text]
    };

    let mut output = String::new();

    for line in lines {
        let rendered = render_line(line, font, opts);
        output.push_str(&rendered);
    }

    output
}

fn render_line(text: &str, font: &Font, opts: &Options) -> String {
    if text.is_empty() {
        return String::new();
    }

    let chars: Vec<char> = if opts.right_to_left {
        text.chars().rev().collect()
    } else {
        text.chars().collect()
    };

    // Get character lines for each character
    let mut char_data: Vec<Vec<String>> = Vec::new();
    for ch in &chars {
        if let Some(lines) = font.get_char(*ch) {
            char_data.push(lines.clone());
        } else {
            // Use space for unknown characters
            if let Some(lines) = font.get_char(' ') {
                char_data.push(lines.clone());
            }
        }
    }

    if char_data.is_empty() {
        return String::new();
    }

    // Combine characters
    let mut output_lines = vec![String::new(); font.height];

    for (char_idx, char_lines) in char_data.iter().enumerate() {
        for (line_idx, line) in char_lines.iter().enumerate() {
            if line_idx < output_lines.len() {
                if char_idx == 0 {
                    // First character
                    output_lines[line_idx].push_str(line);
                } else {
                    // Combine with previous
                    combine_lines(&mut output_lines[line_idx], line, opts);
                }
            }
        }
    }

    // Apply justification and trim
    apply_justification(&output_lines, opts)
}

fn combine_lines(output: &mut String, new_line: &str, opts: &Options) {
    if opts.full_width {
        // Full width mode: add space between characters
        output.push(' ');
        output.push_str(new_line);
    } else if opts.kerning {
        // Kerning mode: remove trailing spaces and add new line
        while output.ends_with(' ') {
            output.pop();
        }
        output.push_str(new_line);
    } else if opts.overlap {
        // Overlap mode: remove one trailing space
        if output.ends_with(' ') {
            output.pop();
        }
        output.push_str(new_line);
    } else {
        // Default smushing mode
        apply_smushing(output, new_line);
    }
}

fn apply_smushing(output: &mut String, new_line: &str) {
    // Remove trailing spaces from output
    let trimmed_output = output.trim_end();
    let output_len = trimmed_output.len();

    // Remove leading spaces from new line
    let trimmed_new = new_line.trim_start();

    // Build result
    output.truncate(output_len);

    if trimmed_output.is_empty() && trimmed_new.is_empty() {
        // Both are spaces
